import React from 'react';
import { MapPin, Phone, MessageSquare, ArrowUpLeft } from 'lucide-react';
import { contactInfo } from '../../data/agency-info';
import { createWhatsAppLink } from '../../lib/whatsapp';

export const Footer: React.FC = () => {
  return (
    <footer id="contact" className="bg-neutral-900 text-neutral-300 pt-16 pb-12 border-t border-neutral-800">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="grid grid-cols-1 md:grid-cols-12 gap-12 pb-12 border-b border-neutral-800">
          
          {/* العمود الأول: تعريف الوكالة */}
          <div className="md:col-span-5 space-y-4">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-white text-neutral-900 flex items-center justify-center font-bold tracking-wider text-base">
                NT
              </div>
              <span className="font-bold text-white text-xl tracking-tight">
                NT Media Agency
              </span>
            </div>
            <p className="text-sm text-neutral-400 leading-relaxed max-w-sm">
              شريكك الاستراتيجي في بناء الحضور الرقمي، صناعة المحتوى الإبداعي، وإدارة الحملات الإعلانية وصناعة الأثر في السوق السعودي.
            </p>
          </div>

          {/* العمود الثاني: العناوين والموقع */}
          <div className="md:col-span-3 space-y-3">
            <h3 className="text-sm font-semibold text-white tracking-wider uppercase">
              المقر الرئيسي
            </h3>
            <div className="flex items-start gap-2.5 text-sm text-neutral-400">
              <MapPin className="w-5 h-5 text-neutral-300 shrink-0 mt-0.5" />
              <span>{contactInfo.location}</span>
            </div>
          </div>

          {/* العمود الثالث: أرقام التواصل والواتساب */}
          <div className="md:col-span-4 space-y-3">
            <h3 className="text-sm font-semibold text-white tracking-wider uppercase">
              الاتصال والتواصل المباشر
            </h3>
            <ul className="space-y-2">
              {contactInfo.phones.map((phone, idx) => {
                const whatsappUrl = createWhatsAppLink(
                  phone,
                  'مرحباً، أود الاستفسار بخصوص خدمات وباقات NT Media Agency.'
                );
                return (
                  <li key={idx} className="flex items-center gap-4 text-sm">
                    <a
                      href={`tel:${phone}`}
                      dir="ltr"
                      className="text-neutral-300 hover:text-white flex items-center gap-2 transition-colors font-mono"
                    >
                      <Phone className="w-4 h-4 text-neutral-400" />
                      {phone}
                    </a>
                    <a
                      href={whatsappUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="inline-flex items-center gap-1 text-xs text-emerald-400 hover:text-emerald-300 transition-colors"
                    >
                      <MessageSquare className="w-3.5 h-3.5" />
                      <span>محادثة واتساب</span>
                      <ArrowUpLeft className="w-3 h-3" />
                    </a>
                  </li>
                );
              })}
            </ul>
          </div>

        </div>

        {/* سطر حقوق الملكية */}
        <div className="pt-8 flex flex-col sm:flex-row items-center justify-between text-xs text-neutral-500 gap-4">
          <p>© {new Date().getFullYear()} NT Media Agency. جميع الحقوق محفوظة.</p>
          <p className="tracking-wide">الرياض، المملكة العربية السعودية</p>
        </div>
      </div>
    </footer>
  );
};